import matplotlib.pyplot as plt
import numpy as np

def task_func(ax, radius):
    if not hasattr(ax, "name") or ax.name != "polar":
        raise TypeError("ax must be a polar Axes")

    try:
        radius = float(radius)
    except (TypeError, ValueError):
        raise TypeError("radius must be a real number") from None

    if radius < 0:
        raise ValueError("radius must be non-negative")

    theta = np.linspace(0.0, 2.0 * np.pi, 361)
    r = np.full(theta.shape, radius, dtype=float)
    ax.plot(theta, r)

    if radius == 0:
        rticks = [0.0]
    else:
        rticks = np.unique(np.round(np.linspace(0.0, radius, 4), 12)).tolist()

    ax.set_rticks(rticks)
    return ax
